html,body{margin:0;height:100%;background:#1e293b;font-family:'Open Sans',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#e2e8f0;}
*{box-sizing:border-box;}
.card{padding:22px 26px 20px;height:calc(var(--appsmith-ui-height)*1px);display:flex;flex-direction:column;}
.mh{display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;}
.mh h3{margin:0;font-size:22px;font-weight:800;color:#f1f5f9;}
.mh .x{cursor:pointer;color:#94a3b8;font-size:22px;line-height:1;}
.mh .x:hover{color:#e2e8f0;}
.sub{color:#93c5fd;font-size:14px;font-weight:600;margin:0 0 14px;}
.tblwrap{flex:1 1 auto;min-height:0;overflow:auto;border:1px solid #334155;border-radius:8px;}
table{width:100%;border-collapse:separate;border-spacing:0;font-size:14px;}
thead th{position:sticky;top:0;background:#1e293b;text-align:left;font-weight:700;color:#cbd5e1;padding:12px 16px;border-bottom:1px solid #334155;z-index:1;}
thead th.r,tbody td.r{text-align:left;}
tbody td{padding:12px 16px;color:#e2e8f0;}
tbody td.name{color:#f1f5f9;}
tbody tr:nth-child(odd) td{background:#0f172a;}
tbody tr:nth-child(even) td{background:transparent;}
.acts{display:flex;justify-content:center;padding-top:18px;flex:0 0 auto;}
.btn{padding:11px 40px;border-radius:8px;font-size:15px;font-weight:600;cursor:pointer;border:1px solid #2563eb;background:#2563eb;color:#fff;}
.btn:hover{background:#1d4ed8;}
.empty{padding:40px;text-align:center;color:#64748b;font-style:italic;}
::-webkit-scrollbar{width:10px;height:10px;background:#1e293b;} ::-webkit-scrollbar-thumb{background:#334155;border-radius:4px;border:2px solid #1e293b;}

