function esc(s){return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}

function render(){
  var m=appsmith.model||{}; var d=m.detail||{};
  var rows=d.rows||[];
  var head='<div class="mh"><h3>Calculated Values</h3><span class="x" id="x">✕</span></div>';
  var sub='<p class="sub">#'+esc(d.billId||"")+' '+esc(d.vendor||"")+(d.endDate?('('+esc(d.endDate)+')'):'')+'</p>';
  var body;
  if(!rows.length){ body='<div class="empty">No details available.</div>'; }
  else {
    body='<div class="tblwrap"><table><thead><tr><th>Name</th><th>Bill Values</th><th>Pro-rated Values</th></tr></thead><tbody>';
    rows.forEach(function(r){
      body+='<tr><td class="name">'+esc(r.name)+'</td><td>'+esc(r.bill)+'</td><td>'+esc(r.pro)+'</td></tr>';
    });
    body+='</tbody></table></div>';
  }
  var root=document.getElementById("root"); if(!root) return;
  root.innerHTML='<div class="card">'+head+sub+body+'<div class="acts"><button class="btn" id="close">Close</button></div></div>';
  var x=document.getElementById("x"); if(x) x.onclick=function(){ appsmith.triggerEvent("onClose"); };
  var c=document.getElementById("close"); if(c) c.onclick=function(){ appsmith.triggerEvent("onClose"); };
}

appsmith.onReady(function(){ render(); appsmith.onModelChange(render); });

